#!/usr/bin/env python3
"""Minimal WAV/raw reader-writer for probing. No numpy needed."""
import struct, sys

def read_wav(path):
    data = open(path,'rb').read()
    assert data[:4]==b'RIFF' and data[8:12]==b'WAVE', 'not wav'
    pos=12; fmt=None; pcm=None
    while pos+8<=len(data):
        cid=data[pos:pos+4]; size=struct.unpack('<I',data[pos+4:pos+8])[0]
        body=data[pos+8:pos+8+size]
        if cid==b'fmt ':
            fmt=struct.unpack('<HHIIHH',body[:16])
        elif cid==b'data':
            pcm=body
        pos += 8+size+(size&1)
    audio_fmt,nch,rate,byterate,align,bits=fmt
    samples=[]
    if audio_fmt==3 and bits==32:
        n=len(pcm)//4; samples=list(struct.unpack('<%df'%n,pcm))
    elif audio_fmt==3 and bits==64:
        n=len(pcm)//8; samples=list(struct.unpack('<%dd'%n,pcm))
    elif audio_fmt==1 and bits==16:
        n=len(pcm)//2; samples=list(struct.unpack('<%dh'%n,pcm))
    elif audio_fmt==1 and bits==32:
        n=len(pcm)//4; samples=list(struct.unpack('<%di'%n,pcm))
    elif audio_fmt==1 and bits==8:
        samples=[b-128 for b in pcm]
    else:
        raise ValueError('fmt=%s bits=%s'%(audio_fmt,bits))
    return dict(fmt=audio_fmt,bits=bits,rate=rate,nch=nch,samples=samples,raw=pcm)

def write_raw_f32(path,samples):
    open(path,'wb').write(struct.pack('<%df'%len(samples),*samples))

def write_raw_s32(path,samples):
    open(path,'wb').write(struct.pack('<%di'%len(samples),*samples))

def write_raw_s16(path,samples):
    open(path,'wb').write(struct.pack('<%dh'%len(samples),*samples))

if __name__=='__main__':
    w=read_wav(sys.argv[1])
    print('fmt=%s bits=%s rate=%s nch=%s n=%d'%(w['fmt'],w['bits'],w['rate'],w['nch'],len(w['samples'])//w['nch']))
    if len(sys.argv)>2:
        n=int(sys.argv[2])
        for i,s in enumerate(w['samples'][:n]):
            print(i,repr(s))

