from rw import read_wav
import math
w=read_wav('dz.wav'); S=w['samples']
o=[int(round(s*2**15)) for s in S]
a,c=1664525,1013904223; mod=1<<32
def run(seed, model, n=400):
    x=seed; bad=0
    for i in range(n):
        x=(x*a+c)%mod; r1=x/2.0**32
        x=(x*a+c)%mod; r2=x/2.0**32
        if model==0: p=int(round(r1+r2-1))
        elif model==1: p=int(round(r1-r2))
        elif model==2: p=math.floor(r1+r2-1+0.5)
        elif model==3: p=math.floor(r1+r2)-1 if r1+r2<1 else math.floor(r1+r2-1)  # variant
        if p!=o[i]: bad+=1
        if bad>20: return bad
    return bad
best=[]
for seed in range(0,200000):
    for m in (0,1,2):
        b=run(seed,m,40)
        if b<3: best.append((seed,m,b))
print(best[:20])
